#!/usr/bin/env bash
# Adjusts the Android project generated by `npx cap add android` (runs on the Ubuntu CI runner).
# Usage: patch-android.sh <version name> <version code>   (from the mobile/ folder)
# Signing: the release build reads the keystore from env NIANPLAY_KEYSTORE (+ _PASSWORD, _ALIAS),
# decoded from the repository secrets by .github/workflows/android.yml.
set -euo pipefail

VERSION="$1"
CODE="$2"
APP="android/app"
GRADLE="$APP/build.gradle"
MANIFEST="$APP/src/main/AndroidManifest.xml"
RES="$APP/src/main/res"

# ── build.gradle ─────────────────────────────────────────────────────────────
perl -0pi -e "s/versionCode \d+/versionCode ${CODE}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$GRADLE"

# Only 64-bit ARM (every current phone): yt-dlp's Python + ffmpeg are ~50 MB per architecture.
# youtubedl-android runs its binaries from the extracted native-libs folder → legacy packaging.
perl -0pi -e 's/(versionName "[^"]*"\n)/$1        ndk { abiFilters "arm64-v8a" }\n/' "$GRADLE"
perl -0pi -e 's/(\n    buildTypes \{)/\n    packaging {\n        jniLibs { useLegacyPackaging = true }\n    }\n    signingConfigs {\n        release {\n            storeFile file(System.getenv("NIANPLAY_KEYSTORE") ?: "missing.p12")\n            storePassword System.getenv("NIANPLAY_KEYSTORE_PASSWORD")\n            keyAlias System.getenv("NIANPLAY_KEY_ALIAS")\n            keyPassword System.getenv("NIANPLAY_KEYSTORE_PASSWORD")\n            storeType "pkcs12"\n        }\n    }$1/' "$GRADLE"
perl -0pi -e 's/(release \{\n\s+minifyEnabled false)/$1\n            signingConfig signingConfigs.release/' "$GRADLE"
grep -q "versionCode ${CODE}" "$GRADLE"
grep -q 'abiFilters "arm64-v8a"' "$GRADLE"
grep -q "useLegacyPackaging = true" "$GRADLE"
grep -q "signingConfig signingConfigs.release" "$GRADLE"

# ── AndroidManifest.xml ──────────────────────────────────────────────────────
perl -0pi -e 's/(<application\n)/$1        android:extractNativeLibs="true"\n/' "$MANIFEST"
perl -0pi -e 's/(android:name="\.MainActivity"\n)/$1            android:screenOrientation="portrait"\n/' "$MANIFEST"
grep -q 'android:extractNativeLibs="true"' "$MANIFEST"
grep -q 'android:screenOrientation="portrait"' "$MANIFEST"

# Name under the icon
perl -pi -e 's|(<string name="app_name">)[^<]*|${1}NianPlay|; s|(<string name="title_activity_main">)[^<]*|${1}NianPlay|' "$RES/values/strings.xml"
grep -q '<string name="app_name">NianPlay' "$RES/values/strings.xml"

# ── Icons and splash (ImageMagick) ───────────────────────────────────────────
command -v convert >/dev/null || { sudo apt-get update -qq && sudo apt-get install -y -qq imagemagick; }
ICON=resources/AppIcon-1024.png
declare -A LEGACY=( [mdpi]=48 [hdpi]=72 [xhdpi]=96 [xxhdpi]=144 [xxxhdpi]=192 )
for d in "${!LEGACY[@]}"; do
  s=${LEGACY[$d]}
  mkdir -p "$RES/mipmap-$d"
  convert "$ICON" -resize "${s}x${s}" "$RES/mipmap-$d/ic_launcher.png"
  convert "$ICON" -resize "${s}x${s}" \( +clone -alpha extract -fill black -colorize 100 -fill white -draw "circle $((s/2)),$((s/2)) $((s/2)),0" \) -alpha off -compose CopyOpacity -composite "$RES/mipmap-$d/ic_launcher_round.png"
  # Adaptive icon foreground: 108 dp canvas, full-bleed art (the launcher mask keeps the center)
  f=$(( s * 108 / 48 ))
  convert "$ICON" -resize "${f}x${f}" "$RES/mipmap-$d/ic_launcher_foreground.png"
done
cat > "$RES/values/ic_launcher_background.xml" <<'EOF'
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">#000000</color>
</resources>
EOF
for f in $(find "$RES" -name 'splash.png'); do
  size=$(identify -format '%wx%h' "$f")
  convert resources/splash-2732.png -resize "${size}^" -gravity center -extent "$size" "$f"
done

echo "--- app/build.gradle (patched)"
cat "$GRADLE"
echo "--- AndroidManifest.xml (patched)"
cat "$MANIFEST"
